effect.shader:
vec4 u_xlat0;
bool u_xlatb0;
vec4 u_xlat1;
vec4 u_xlat2;
bool u_xlatb2;
float u_xlat3;
bool u_xlatb3;
float u_xlat4;
vec2 u_xlat6;
vec2 u_xlat7;
float u_xlat9;
void main()
{
    u_xlat0.x = min(_y_scale, _x_scale);
    u_xlat3 = u_xlat0.x * 0.5 + (-_outline_size);
    u_xlat3 = min(u_xlat3, _blur);
    u_xlat0.y = max(u_xlat3, 0.0);
    u_xlat0.x = u_xlat0.x * 0.5 + (-u_xlat0.y);
    u_xlat0.x = u_xlat0.x + (-_outline_size);
    u_xlat0.x = min(u_xlat0.x, u_xlat0.y);
    u_xlat0.x = max(u_xlat0.x, 0.0);
    u_xlat6.x = u_xlat0.y + _outline_size;
    u_xlat1.xy = acScreenNorm.xy * vec2(_x_scale, _y_scale);
    u_xlat7.xy = vec2(_x_scale, _y_scale) * vec2(0.5, 0.5);
    u_xlat9 = min(u_xlat7.x, 0.0);
    u_xlat9 = min(u_xlat7.y, u_xlat9);
    u_xlat7.x = acScreenNorm.y * _y_scale + u_xlat7.y;
    u_xlat2.xy = vec2(_x_scale, _y_scale) * vec2(0.5, 0.5) + (-vec2(u_xlat9));
    u_xlat1.xy = abs(u_xlat1.xy) + (-u_xlat2.xy);
    u_xlat2.xy = max(u_xlat1.xy, vec2(0.0, 0.0));
    u_xlat1.x = max(u_xlat1.y, u_xlat1.x);
    u_xlat1.x = min(u_xlat1.x, 0.0);
    u_xlat4 = dot(u_xlat2.xy, u_xlat2.xy);
    u_xlat4 = sqrt(u_xlat4);
    u_xlat1.x = u_xlat4 + u_xlat1.x;
    u_xlat6.y = u_xlat9 + (-u_xlat1.x);
    u_xlat6.x = (-u_xlat6.x) + u_xlat6.y;
    u_xlat0.xy = u_xlat6.xy / u_xlat0.xy;
    u_xlat0.xy = clamp(u_xlat0.xy, 0.0, 1.0);
    u_xlat2 = u_xlat0.xxxx * (-_outline_color) + _outline_color;
    u_xlat2.w = u_xlat0.y * u_xlat2.w;
    u_xlat0.x = (-_outline_size) * 3.0 + _y_scale;
    u_xlatb0 = u_xlat7.x<u_xlat0.x;
    u_xlatb3 = _outline_size==0.0;
    u_xlatb0 = u_xlatb0 || u_xlatb3;
    u_xlat1 = (bool(u_xlatb3)) ? vec4(0.0, 0.0, 0.0, 0.0) : u_xlat2;
    u_xlat0 = (bool(u_xlatb0)) ? vec4(0.0, 0.0, 0.0, 0.0) : u_xlat2;
    u_xlatb2 = int(_style)==1;
    fragColor = (bool(u_xlatb2)) ? u_xlat0 : u_xlat1;
    return;
}
